java_file = sys.argv[3] if len(sys.argv) > 3 else os.path.join(root, 'src', 'main', 'java', 'org', 'libxmq', 'imp', 'xml', 'XmlHtml.java')

def c_values(name):
    """The values of the C array name in html5ent.inc, char literals as their codes."""
    m = re.search(r'static const unsigned (?:char|short) ' + name + r'\[(\d+)\] = \{(.*?)\n\};', ent, re.S)
    values = []
    for t in re.findall(r"'(?:\\.|[^'])'|\d+", m.group(2)):
        if t.startswith("'"):
            c = t[1:-1]
            values.append(ord(c[1]) if c.startswith('\\') else ord(c))
        else:
            values.append(int(t))
    assert len(values) == int(m.group(1)), name
    return values

def java_string(values):
    """A java string literal with one char per value (octal escapes below 256, never a \\u escape
    of a line break, quote or backslash), split into lines."""
    parts = []
    for v in values:
        if 0x20 <= v < 0x7f and chr(v) not in '"\\':
            parts.append(chr(v))
        elif v < 256:
            parts.append('\\%03o' % v)
        else:
            parts.append('\\u%04x' % v)
    lines = []
    for i in range(0, len(parts), 40):
        lines.append('        "' + ''.join(parts[i:i+40]) + '"')
    return ' +\n'.join(lines)

